import{C as e,L as t,S as n,V as r,X as i,_ as a,b as o,x as s}from"./vue-Vea_iehr.js";import{oi as c}from"./common-BkM8iD8A.js";import"./pve_net_schematization--A38gB4A.js";var l=JSON.parse(`{"path":"/router/routeros/aduf7b9w/","title":"正版系统激活 | RouterOS","lang":"zh-CN","frontmatter":{"title":"正版系统激活","createTime":"2026/08/25 13:51:48","permalink":"/router/routeros/aduf7b9w/","copyright":{"creation":"reprint","license":"CC-BY-4.0","source":"https://gitee.com/callmer/routeros_toss_notes/tree/master","author":{"name":"callmer","url":"https://gitee.com/callmer"}}},"readingTime":{"minutes":4.68,"words":1404},"git":{},"filePathRelative":"router/routeros/01.正版系统激活.md","headers":[]}`),u={name:`01.正版系统激活.md`};function d(c,l,u,d,f,p){let m=r(`VPLink`);return t(),o(`div`,null,[l[3]||=a(`h2`,{id:`_1-系统激活`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#_1-系统激活`},[a(`span`,null,`1.系统激活`)])],-1),l[4]||=a(`p`,null,[a(`strong`,null,`注意：对于官方 RouterOS 路由器产品（包括 RouterBOARD ），系统自带授权，可跳过本篇内容。`)],-1),a(`p`,null,[l[1]||=n(`在上一篇文章 `,-1),e(m,{href:`./00.PVE%E4%B8%8B%E5%AE%89%E8%A3%85%E7%B3%BB%E7%BB%9F.md`},{default:i(()=>[...l[0]||=[n(`00.PVE下安装系统`,-1)]]),_:1}),l[2]||=n(` 中，已经在 PVE 环境下安装好了 RouterOS 。`,-1)]),l[5]||=s(`<p>本文将告诉大家如何激活正版 RouterOS 系统。</p><h3 id="_1-1-购买-license" tabindex="-1"><a class="header-anchor" href="#_1-1-购买-license"><span>1.1.购买 License</span></a></h3><p>因为使用的是原装系统，不像其它 “克隆版” RouterOS 虚拟机镜像，导入后开机就是激活状态。</p><p>因此需要使用 Mikrotik 的官方 <code>License</code> 来激活 RouterOS 系统。</p><p>首先需要用邮箱注册 Mikrotik 账号，注册地址为 <code>https://mikrotik.com/client</code> 。</p><p>然后使用某宝或其他渠道购买一个 <code>License</code> ，CHR 的 <code>License</code> 分为 P1、P10、PU 三个版本，其区别在于 “网口限速” 。</p><p>对于有 2.5G 网口的设备，推荐购买 P10 授权。</p><table><thead><tr><th>授权等级</th><th>限速值</th><th>说明</th></tr></thead><tbody><tr><td>P1</td><td><code>1Gbps</code></td><td>物理接口为千兆设备使用</td></tr><tr><td>P10</td><td><code>10Gbps</code></td><td>物理接口为千兆以上万兆以下设备使用（推荐）</td></tr><tr><td>PU</td><td><code>不限速</code></td><td>任意速度的物理接口均可使用</td></tr></tbody></table><p>授权购买后，打开 Mikrotik 官网并登录账号，进入到账户中心。在 <code>Transfer prepaid keys</code> 页面会看到有一个新的 <code>License</code> 。</p><p><strong>注意：</strong></p><ul><li><p><strong>为了彻底避免授权被非法撤销，建议一律购买 <code>P</code> 系授权。</strong></p></li><li><p><strong>只有这里显示出新购买的 <code>Transfer prepaid keys</code> 才表示这个 <code>License</code> 真正属于你了。</strong></p></li><li><p><strong>经过实际测试，<code>Transfer prepaid keys</code> 既可生成 CHR 所需的 <code>P</code> 系授权，也能生成 x86 所需的 <code>L</code> 系授权。</strong></p></li></ul><p><img src="/images/router/routeros/p01/buy_new_license.png" alt="新的License" width="1280" height="871"></p><h3 id="_1-2-routeros-联网" tabindex="-1"><a class="header-anchor" href="#_1-2-routeros-联网"><span>1.2. RouterOS 联网</span></a></h3><p>由于 Winbox3 只支持 Windows 系统，在 macOS 或 Linux 系统下需使用 Winbox4 。</p><p>参考下图中各网口对应关系，连接网线：</p><ul><li>将 PVE 服务器的 ETH0 网口，与 <code>前置路由器</code> 或 <code>光猫</code> LAN 口相连。</li><li>将 PVE 服务器的 ETH1 到 ETH3 中的任意网口，与 Windows 设备的网口相连。</li></ul><p><img src="/images/router/routeros/p01/pve_net_schematization.jpeg" alt="PVE网络规划" width="1730" height="1220"></p><p>打开 Winbox ，此时 Winbox 会识别到一个新的 RouterOS 设备，并显示出该设备的 MAC 地址和 IP 地址（ <code>0.0.0.0</code> ）。</p><p>点击 MAC 地址来登录 RouterOS，默认账户 <code>admin</code> ，无需密码即可登录。</p><p><img src="/images/router/routeros/p01/wb_login.jpeg" alt="Winbox登录" width="2234" height="1330"></p><p>对于使用官方 ISO 镜像安装的 RouterOS ，首次登录系统后可能显示如下内容。</p><p>该对话框表示该 RouterOS 未被授权，此时 RouterOS 处于 “试用” 状态，时长为 24 小时，且带宽被限制在 <code>1Mbps</code> 。</p><p><img src="/images/router/routeros/p01/wb_welcome.png" alt="未授权提示" width="1050" height="762"></p><p>由于后续 <code>admin</code> 账户将作为 “只读” 账户使用，因此设置一个方便记忆的密码即可。</p><p><img src="/images/router/routeros/p01/wb_first_pwd.jpeg" alt="账户密码过期" width="1400" height="1040"></p><p>点击 Winbox 左侧导航 <code>IP</code> 菜单的子菜单 <code>DHCP Client</code> ，查看当前 DHCPv4 客户端状态。</p><p>一般情况下， RouterOS 会在第一个网口 <code>ether1</code> 上自动创建一个 <code>DHCP Client</code> 。</p><p>该 <code>DHCP Client</code> 将从 <code>前置路由器</code> 或 <code>光猫</code> 中获取 IPv4 地址，并自动设置系统 DNS 。</p><p><img src="/images/router/routeros/p01/wb_default_dhcp_client.jpeg" alt="RouterOS默认DHCP客户端" width="2410" height="1180"></p><p>如果 <code>DHCP Client</code> 中无数据，则需要手动创建，点击 <code>New</code> ：</p><p><img src="/images/router/routeros/p01/wb_add_dhcp_client.jpeg" alt="RouterOS创建DHCP客户端" width="1800" height="1200"></p><h3 id="_1-3-更新-system-id" tabindex="-1"><a class="header-anchor" href="#_1-3-更新-system-id"><span>1.3.更新 System ID</span></a></h3><p>此时 RouterOS 已经联网，点击左侧导航 <code>System</code> 菜单的子菜单 <code>License</code> 。</p><p>如果希望更换 <code>System ID</code>，或从 P1 升级到更高级授权，可以点击 <code>Generate New ID</code> 来更新。</p><p><img src="/images/router/routeros/p01/new_system_id.jpeg" alt="获取新SystemID" width="2000" height="1200"></p><p>系统会提示 “旧授权将不再可用，是否确认” ，点击 <code>OK</code> 即可。</p><p><strong>注意：谨慎使用 <code>System ID</code> 更新功能，目前只有试用状态的 RouterOS 可更新 <code>System ID</code> 。</strong></p><p><img src="/images/router/routeros/p01/confirm_new_system_id.jpeg" alt="确认更新SystemID" width="1200" height="762"></p><p>更新 <code>System ID</code> 后，接下来需要更新 <code>License</code> 授权信息。</p><p>点击 <code>Renew License</code> ，输入 Mikrotik 的账户和密码，并选择对应的授权级别（演示为 P10 授权），点击 <code>Start</code> ：</p><p><img src="/images/router/routeros/p01/renew_license.jpeg" alt="刷新授权信息" width="1200" height="1000"></p><p>当下方提示显示为 <code>done</code> ，则表示 <code>License</code> 信息更新成功，<code>License</code> 对话框将显示授权的自动校验时间：</p><p><img src="/images/router/routeros/p01/renew_license_done.jpeg" alt="刷新授权信息完成" width="1200" height="1000"></p><p>授权更新完成后，回到 <code>IP</code> 菜单的子菜单 <code>DHCP Client</code> ，将 <code>DHCP Client</code> 移除。</p><p><img src="/images/router/routeros/p01/wb_remove_dhcp_client.jpeg" alt="RouterOS移除DHCP客户端" width="1600" height="1000"></p><h3 id="_1-4-激活系统" tabindex="-1"><a class="header-anchor" href="#_1-4-激活系统"><span>1.4.激活系统</span></a></h3><p>再次打开 Mikrotik 的账户中心，在 <code>All CHR Keys</code> 页面，会出现刚刚刷新了 <code>License</code> 授权信息的 <code>System ID</code> 。</p><p>接下来需要更新授权信息，点击右侧 <code>Upgrade</code> ：</p><p><img src="/images/router/routeros/p01/license_new_system.png" alt="授权新系统" width="1280" height="602"></p><p>进入授权升级页面，左下角可以看到已付费 <code>License</code> 信息。</p><p>根据使用需求，选择授权级别 <code>Level</code> （演示中为 P10 授权），并点击 <code>Upgrade</code> ：</p><p><img src="/images/router/routeros/p01/choose_level.png" alt="选择授权级别" width="1280" height="595"></p><p>点击 <code>Pay using Prepaid key</code> ，即可完成授权：</p><p><img src="/images/router/routeros/p01/pay_with_key.png" alt="使用key支付" width="1280" height="432"></p><p>回到 <code>All CHR keys</code> 页面，可以看到系统的授权信息已经变更：</p><p><img src="/images/router/routeros/p01/system_licensed.png" alt="授权注册完成" width="1280" height="841"></p><h3 id="_1-5-授权转移" tabindex="-1"><a class="header-anchor" href="#_1-5-授权转移"><span>1.5.授权转移</span></a></h3><p>由于虚拟机可能被重装，CHR 版本 RouterOS 的授权 <code>License</code> 是可以在不同虚拟机之间转移的。</p><p>当重装了 RouterOS，或者通过前面步骤更新了 <code>System ID</code> 后，可在 Mikrotik 的账户中心中对授权进行转移。</p><p>在 Mikrotik 账户中心的 <code>All CHR Keys</code> 页面，记住新系统的 <code>System ID</code> ，然后点击需要转移的授权的 <code>Transfer</code> ：</p><p><img src="/images/router/routeros/p01/find_new_system_id.jpeg" alt="记住新系统SystemID" width="1600" height="900"></p><p>通过右侧下拉列表找到新系统的 <code>System ID</code> ，然后点击 <code>Transfer subscription</code> ，即可授权转移：</p><p><img src="/images/router/routeros/p01/choose_new_system_id.jpeg" alt="找到新系统SystemID" width="1600" height="520"></p><p>授权转移完成：</p><p><img src="/images/router/routeros/p01/license_transfer_done.jpeg" alt="授权转移完成" width="1600" height="592"></p><p>回到 <code>All CHR keys</code> 页面，可以看到新系统已被正确授权，而老系统的授权已经失效：</p><p><img src="/images/router/routeros/p01/check_new_system_license.jpeg" alt="系统授权确认" width="1600" height="930"></p><p>至此，RouterOS 系统激活步骤完成。</p>`,68)])}var f=c(u,[[`render`,d]]);export{l as _pageData,f as default};